public static class Cache {
    static readonly Dictionary<string, Image>
        images = new();

    public static Image Obtenir(string chemin) {
        if (!images.TryGetValue(chemin, out var img)) {
            img = Image.Charger(chemin);
            images[chemin] = img;
        }
        return img;
    }
}

